using Farm360.Core.Data;

namespace Farm360.Sample.Domain;

/// <summary>
/// The module's example aggregate. All state changes go through its methods, so the rules live in one place. Replace it with your own:
/// keep the patterns (an aggregate root for ETags, soft delete, audit fields filled by the platform, keys generated by the database provider).
/// </summary>
public sealed class Item : BaseEntity, IAggregateRoot, ISoftDeletable
{
    public const int MaxNameLength = 200;

    private Item()
    {
    }

    public Item(string name)
    {
        Name = name.Trim();
    }

    public string Name { get; private set; } = "";

    public bool IsDeleted { get; private set; }

    public DateTime? DeletedOn { get; private set; }

    public void Rename(string name) => Name = name.Trim();

    public void MarkDeleted(DateTime utcNow)
    {
        IsDeleted = true;
        DeletedOn = utcNow;
    }
}
